        // ========================================
        // Generated Python Grammar Parsing Methods
        // ========================================

        // Helper methods
        private GeneratedTokenInfo? CurrentToken => _position < _tokens.Count ? _tokens[_position] : null;

        private void Advance()
        {
            if (_position < _tokens.Count) _position++;
        }

        /// <summary>
        /// Expect a specific token value. Returns the token if it matches, null otherwise.
        /// CPython 3.12 PEG compatible.
        /// </summary>
        private GeneratedTokenInfo? Expect(string expected)
        {
            if (CurrentToken?.Value == expected)
            {
                var token = CurrentToken;
                Advance();
                return token;
            }
            return null;
        }

        /// <summary>
        /// Skip NL tokens for implicit line joining (CPython 3.12 compatible)
        /// </summary>
        private void SkipNL()
        {
            while (CurrentToken?.Type == PyToken.Type.NL)
            {
                Advance(); // skip NL token
            }
        }

        private int Mark() => _position;

        private void Reset(int mark) => _position = mark;

        private T? GetMemo<T>(string ruleName) where T : GeneratedAstNode
        {
            var key = (_position, ruleName);
            return _memoCache.TryGetValue(key, out var value) ? value as T : default;
        }

        private void SetMemo<T>(string ruleName, T? value) where T : GeneratedAstNode
        {
            var key = (_position, ruleName);
            _memoCache[key] = value;
        }

        private List<T> ParseZeroOrMore<T>(Func<T?> parseFunc) where T : class
        {
            var results = new List<T>();
            while (true)
            {
                var startPos = _position;
                var result = parseFunc();
                if (result == null)
                {
                    _position = startPos;
                    break;
                }
                results.Add(result);
            }
            return results;
        }

        private List<T>? ParseOneOrMore<T>(Func<T?> parseFunc) where T : class
        {
            var results = ParseZeroOrMore(parseFunc);
            return results.Count > 0 ? results : null;
        }

        private T? ParseOptional<T>(Func<T?> parseFunc) where T : class
        {
            var startPos = _position;
            var result = parseFunc();
            if (result == null)
            {
                _position = startPos;
            }
            return result;
        }

        private T? ParseGroup<T>(Func<T?> parseFunc) where T : class
        {
            return parseFunc();
        }

        private bool AtEndOfFile()
        {
            return _position >= _tokens.Count || CurrentToken?.Type.ToString() == "ENDMARKER";
        }

        private bool ExpectOperator(string op)
        {
            if (CurrentToken?.Type.ToString() == "OP" && CurrentToken?.Value == op)
            {
                Advance();
                return true;
            }
            return false;
        }

        private string? ExpectTokenType(string tokenType)
        {
            if (CurrentToken?.Type.ToString() == tokenType)
            {
                var value = CurrentToken?.Value;
                Advance();
                return value;
            }
            return null;
        }

        // ============ Entry Points from @trailer ============
        
// CPython 3.12: Entry point for file parsing
public GeneratedMod ParseFile()
{
    var result = File();
    if (result == null || _pendingSyntaxError != null)
    {
        var errorMsg = _pendingSyntaxError ?? "invalid syntax";

        // CPython 3.12: Get error location from known error token or current position
        // _knownErrToken is set by RaiseSyntaxError, but for parse failures we use _position
        GeneratedTokenInfo errorToken = _knownErrToken;

        // If no known error token, use the token at current parse position
        if (errorToken == null && _position < _tokens.Count)
        {
            errorToken = _tokens[_position];
        }
        // Fallback: use first token if no error token found
        else if (errorToken == null && _tokens.Count > 0)
        {
            errorToken = _tokens[0];
        }

        // CPython 3.12: If we're at a valid position, the error token should be here
        if (errorToken != null)
        {
            var ex = new PySyntaxErrorException(errorMsg, _filename,
                errorToken.Line, errorToken.Column,
                errorToken.EndColumn,
                GetSourceLine(errorToken.Line));
            throw ex;
        }

        throw new PySyntaxErrorException(errorMsg);
    }
    return result;
}

// CPython 3.12: Entry point for interactive parsing
public GeneratedMod ParseInteractive()
{
    var result = Interactive();
    if (result == null || _pendingSyntaxError != null)
    {
        var errorMsg = _pendingSyntaxError ?? "invalid syntax";

        GeneratedTokenInfo errorToken = _knownErrToken;
        if (errorToken == null && _position < _tokens.Count)
        {
            errorToken = _tokens[_position];
        }
        else if (errorToken == null && _tokens.Count > 0)
        {
            errorToken = _tokens[0];
        }

        if (errorToken != null)
        {
            var ex = new PySyntaxErrorException(errorMsg, _filename,
                errorToken.Line, errorToken.Column,
                errorToken.EndColumn,
                GetSourceLine(errorToken.Line));
            throw ex;
