        /// <summary>
        /// type_params[asdl_type_param_seq*]: '[' t=type_param_seq ']'
        /// Parse optional type parameters for PEP 695
        /// </summary>
        public List<GeneratedTypeParam>? ParseTypeParams()
        {
            // Check for '[' - if not present, return null (no type parameters)
            if (CurrentToken?.Type != PyToken.Type.OP || CurrentToken?.Value != "[")
            {
                return null;
            }

            var startPos = _position;
            Advance(); // consume '['

            var typeParams = new List<GeneratedTypeParam>();

            // Parse type_param_seq: comma-separated type parameters
            while (CurrentToken != null)
            {
                var typeParam = ParseTypeParam();
                if (typeParam == null)
                {
                    Console.WriteLine($"[DEBUG] ParseTypeParams: Failed to parse type parameter at position {_position}");
                    _position = startPos;
                    return null;
                }

                typeParams.Add(typeParam);

                // Check for comma or end
                if (CurrentToken?.Type == PyToken.Type.OP && CurrentToken?.Value == ",")
                {
                    Advance(); // consume ','
                    continue;
                }
                else if (CurrentToken?.Type == PyToken.Type.OP && CurrentToken?.Value == "]")
                {
                    break; // End of type parameters
                }
                else
                {
                    Console.WriteLine($"[DEBUG] ParseTypeParams: Expected ',' or ']' at position {_position}");
                    _position = startPos;
                    return null;
                }
            }

            // Expect ']'
            if (Expect("]") == null)
            {
                Console.WriteLine($"[DEBUG] ParseTypeParams: Failed to match ']' at position {_position}");
                _position = startPos;
                return null;
            }

            Console.WriteLine($"[DEBUG] ParseTypeParams: Successfully parsed {typeParams.Count} type parameters");
            return typeParams;
        }

        /// <summary>
        /// type_param[type_param_ty]: TypeVar | TypeVarTuple | ParamSpec
        /// Parse individual type parameter (T, *Ts, **P)
        /// </summary>
        public GeneratedTypeParam? ParseTypeParam()
        {
            var startPos = _position;
            var _start_lineno = _tokens[startPos].Line;
            var _start_col_offset = _tokens[startPos].Column;

            // Check for TypeVarTuple: '*' NAME
            if (CurrentToken?.Type == PyToken.Type.OP && CurrentToken?.Value == "*")
            {
                Advance(); // consume '*'
                var nameToken = ExpectName();
                if (nameToken == null)
                {
                    Console.WriteLine($"[DEBUG] ParseTypeParam: Failed to parse TypeVarTuple name at position {_position}");
                    _position = startPos;
                    return null;
                }

                var name = nameToken.Value;
                Console.WriteLine($"[DEBUG] ParseTypeParam: Parsed TypeVarTuple '{name}'");
                var _end_lineno = _tokens[_position - 1].EndLine;
                var _end_col_offset = _tokens[_position - 1].EndColumn;
                return _PyAST_TypeVarTuple(name, _start_lineno, _start_col_offset, _end_lineno, _end_col_offset);
            }

            // Check for ParamSpec: '**' NAME
            if (CurrentToken?.Type == PyToken.Type.OP && CurrentToken?.Value == "**")
            {
                Advance(); // consume '**'
                var nameToken = ExpectName();
                if (nameToken == null)
                {
                    Console.WriteLine($"[DEBUG] ParseTypeParam: Failed to parse ParamSpec name at position {_position}");
                    _position = startPos;
                    return null;
                }

                var name = nameToken.Value;
                Console.WriteLine($"[DEBUG] ParseTypeParam: Parsed ParamSpec '{name}'");
                var _end_lineno = _tokens[_position - 1].EndLine;
                var _end_col_offset = _tokens[_position - 1].EndColumn;
                return _PyAST_ParamSpec(name, _start_lineno, _start_col_offset, _end_lineno, _end_col_offset);
            }

            // TypeVar: NAME [':' expression]
            var typeVarNameToken = ExpectName();
            if (typeVarNameToken == null)
            {
                Console.WriteLine($"[DEBUG] ParseTypeParam: Failed to parse TypeVar name at position {_position}");
                _position = startPos;
                return null;
            }

            var typeVarName = typeVarNameToken.Value;

            // Optional bound: ':' expression
            GeneratedExpr? bound = null;
            if (CurrentToken?.Type == PyToken.Type.OP && CurrentToken?.Value == ":")
            {
                Advance(); // consume ':'
                bound = Expression();
                if (bound == null)
                {
                    Console.WriteLine($"[DEBUG] ParseTypeParam: Failed to parse TypeVar bound at position {_position}");
                    _position = startPos;
                    return null;
                }
            }

            Console.WriteLine($"[DEBUG] ParseTypeParam: Parsed TypeVar '{typeVarName}' with bound: {bound != null}");
            var _end_lineno2 = _tokens[_position - 1].EndLine;
            var _end_col_offset2 = _tokens[_position - 1].EndColumn;
            return _PyAST_TypeVar(typeVarName, bound, _start_lineno, _start_col_offset, _end_lineno2, _end_col_offset2);
        }

        // ========== CPython 3.12: String parsing helper methods ==========

        // CPython: _PyPegen_constant_from_string
        // Convert STRING token to Constant AST node - accepts both token and already-converted constant
        private GeneratedExpr _PyPegen_constant_from_string(GeneratedPtr tokenOrConstant)
        {
            // Handle if already converted to constant (from StringToken)
            if (tokenOrConstant is GeneratedConstant constant)
                return constant; // Already converted, return as-is

            // Handle raw token
            if (tokenOrConstant is GeneratedTokenInfo token)
            {
                // STRING token value includes quotes (e.g., \"hello\", 'world', r\"raw\")
                var value = token.Value;
                // Decode string literal: remove quotes and handle escape sequences
                var decoded = DecodeStringLiteral(value);
                var pyConstant = new GeneratedPyConstantString(decoded);
                return _PyAST_Constant(pyConstant, null, token.Line, token.Column, token.EndLine, token.EndColumn);
            }

            throw new ArgumentException("Expected GeneratedTokenInfo or GeneratedConstant", nameof(tokenOrConstant));
        }

        // CPython: _PyPegen_concatenate_strings
        // Concatenate multiple string literals: \"a\" \"b\" -> \"ab\"
        private GeneratedExpr _PyPegen_concatenate_strings(GeneratedExprSeq strings, int lineno, int col, int? end_lineno, int? end_col)
        {
            // Single string: return as-is
            if (strings.Count == 1)
                return strings[0];

            // Multiple strings: concatenate values
            var concatenated = new System.Text.StringBuilder();
            foreach (var str in strings)
            {
                if (str is GeneratedConstant constant && constant.Value is GeneratedPyConstantString strConst)
                {
                    concatenated.Append(strConst.Value);
                }
            }
            var pyConstant = new GeneratedPyConstantString(concatenated.ToString());
            return _PyAST_Constant(pyConstant, null, lineno, col, end_lineno ?? 0, end_col ?? 0);
        }

        // CPython: _PyPegen_parse_string (string_parser.c)
        // Decode string literal: remove quotes and handle escape sequences
        private string DecodeStringLiteral(string literal)
        {
            if (string.IsNullOrEmpty(literal) || literal.Length < 2)
                return literal;

            // Check for raw string prefix
            bool isRawString = literal.StartsWith("r'") || literal.StartsWith("r\"") || 
                               literal.StartsWith("R'") || literal.StartsWith("R\"");
            int startIdx = isRawString ? 2 : 1;
            int endIdx = literal.Length - 1;

            // Extract content between quotes
            var content = literal.Substring(startIdx, endIdx - startIdx);

            // Raw strings: no escape processing
            if (isRawString)
                return content;

            // Process escape sequences (CPython 3.12 compatible)
            var result = new System.Text.StringBuilder(content.Length);
            for (int i = 0; i < content.Length; i++)
            {
                if (content[i] == '\\' && i + 1 < content.Length)
                {
                    char next = content[i + 1];
                    switch (next)
                    {
                        case 'n': result.Append('\n'); i++; break;
                        case 't': result.Append('\t'); i++; break;
                        case 'r': result.Append('\r'); i++; break;
                        case '\\': result.Append('\\'); i++; break;
                        case '\'': result.Append('\''); i++; break;
                        case '\"': result.Append('\"'); i++; break;
                        case '0': result.Append('\0'); i++; break;
                        default: result.Append('\\'); break; // Unknown escape: keep backslash
                    }
                }
                else
                {
                    result.Append(content[i]);
                }
            }
            return result.ToString();
        }

        // CPython: _PyPegen_joined_str (pegen.c)
        // Create JoinedStr node from f-string tokens
        private GeneratedExpr _PyPegen_joined_str(GeneratedTokenInfo start, GeneratedExprSeq middle, GeneratedTokenInfo end)
        {
            if (start == null || end == null)
                return null;

            // Create list of string parts and expressions
            var values = middle ?? new GeneratedExprSeq();
            int endLine = end.EndLine > 0 ? end.EndLine : end.Line;
            int endCol = end.EndColumn > 0 ? end.EndColumn : end.Column;
            return _PyAST_JoinedStr(values, start.Line, start.Column, endLine, endCol);
        }

        // CPython: _PyPegen_constant_from_token
        // Create Constant node from FSTRING_MIDDLE token
        private GeneratedExpr _PyPegen_constant_from_token(GeneratedTokenInfo token)
        {
            if (token == null)
                return null;

            // FSTRING_MIDDLE contains plain text (no quotes needed)
            var pyConstant = new GeneratedPyConstantString(token.Value);
            int endLine = token.EndLine > 0 ? token.EndLine : token.Line;
            int endCol = token.EndColumn > 0 ? token.EndColumn : token.Column;
            return _PyAST_Constant(pyConstant, null, token.Line, token.Column, endLine, endCol);
        }

        // CPython: _PyPegen_check_fstring_conversion (action_helpers.c)
        // Validate f-string conversion (!s, !r, !a)
        private ResultTokenWithMetadata _PyPegen_check_fstring_conversion(GeneratedTokenInfo conv_token, GeneratedExpr conv)
        {
            if (conv == null || conv_token == null)
                return null;

            // conv should be a Name node
            if (conv is GeneratedName name)
            {
                var conversion = name.Id;
                // CPython 3.12: Only 's', 'r', 'a' are valid
                if (conversion != "s" && conversion != "r" && conversion != "a")
                {
                    RaiseErrorKnownLocation(conv_token, $"f-string: invalid conversion character '{conversion}': expected 's', 'r', or 'a'");
                    return null;
                }

                // Return metadata with conversion token
                return new ResultTokenWithMetadata { Token = conv_token, Metadata = conversion };
            }

            return null;
        }

        // CPython: _PyPegen_formatted_value (action_helpers.c)
        // Create FormattedValue node for f-string replacement field
        private GeneratedExpr _PyPegen_formatted_value(GeneratedExpr expr, GeneratedTokenInfo debug_expr, GeneratedPtr conversion, GeneratedPtr format, GeneratedTokenInfo rbrace, int lineno, int col, int end_lineno, int end_col)
        {
            if (expr == null)
                return null;

            #if DEBUG_FSTRING_LOG
            Console.WriteLine($"[FSTRING-FORMATTED_VALUE] _PyPegen_formatted_value called:");
            Console.WriteLine($"  conversion is null: {conversion == null}");
            if (conversion != null)
            {
                Console.WriteLine($"  conversion.GetType(): {conversion.GetType().Name}");
                if (conversion is ResultTokenWithMetadata convDebug)
                {
                    Console.WriteLine($"  conversion.Metadata: {convDebug.Metadata}");
                    if (convDebug.Metadata != null)
                        Console.WriteLine($"  conversion.Metadata.GetType(): {convDebug.Metadata.GetType().Name}");
                }
            }
            #endif

            // Parse conversion character (!s, !r, !a)
            int conversionChar = -1; // -1 = no conversion
            if (conversion is ResultTokenWithMetadata convMeta && convMeta.Metadata is GeneratedIdentifier convId)
            {
                string convStr = convId.Value;
                if (convStr.Length > 0)
                    conversionChar = convStr[0]; // 's', 'r', or 'a'
            }

            // Parse format spec
            GeneratedExpr formatSpec = null;
            if (format is ResultTokenWithMetadata fmtMeta && fmtMeta.Metadata is GeneratedExpr formatExpr)
            {
                formatSpec = formatExpr;
            }

            return _PyAST_FormattedValue(expr, conversionChar, formatSpec, lineno, col, end_lineno, end_col);
        }

        // CPython: _PyPegen_decoded_constant_from_token
        // Create Constant from token without decoding (for FSTRING_MIDDLE)
        private GeneratedExpr _PyPegen_decoded_constant_from_token(GeneratedTokenInfo token)
        {
            // Same as _PyPegen_constant_from_token - FSTRING_MIDDLE is already decoded
            return _PyPegen_constant_from_token(token);
        }

        // CPython: _PyPegen_setup_full_format_spec (action_helpers.c)
        // Create format spec from colon and spec parts
        private ResultTokenWithMetadata _PyPegen_setup_full_format_spec(GeneratedTokenInfo colon, GeneratedExprSeq spec, int lineno, int col, int end_lineno, int end_col)
        {
            if (colon == null)
                return null;

            // If no spec parts, create empty JoinedStr
            if (spec == null || spec.Count == 0)
            {
                var emptySeq = new GeneratedExprSeq();
                var emptyJoined = _PyAST_JoinedStr(emptySeq, lineno, col, end_lineno, end_col);
                return new ResultTokenWithMetadata { Token = colon, Metadata = emptyJoined };
            }

            // Create JoinedStr from spec parts
            var joinedStr = _PyAST_JoinedStr(spec, lineno, col, end_lineno, end_col);
            return new ResultTokenWithMetadata { Token = colon, Metadata = joinedStr };
        }

    }
}
